'use strict';
// שרת "סט": חשבונות (שם משתמש וסיסמה) ואחסון נתונים. בלי תלויות חיצוניות, רק Node.js 18 ומעלה.
const http = require('http'), fs = require('fs'), path = require('path'), crypto = require('crypto');

const PORT = Number(process.env.PORT) || 3000;
const COACH_KEY = process.env.COACH_KEY || '';            // אם מוגדר, נדרש כדי להירשם כמאמן
const DATA_FILE = process.env.DATA_FILE || path.join(__dirname, 'data', 'db.json');
const MAX_BODY = 3 * 1024 * 1024;
const SESSION_MS = 14 * 24 * 3600 * 1000;   // התחברות פוקעת אחרי 14 יום בלי שימוש, ומתחדשת בכל שימוש

/* ---------- אחסון בקובץ ---------- */
let db = { users: {}, docs: {}, sessions: {}, resets: {} };
try { db = Object.assign(db, JSON.parse(fs.readFileSync(DATA_FILE, 'utf8'))); } catch (e) {}
fs.mkdirSync(path.dirname(DATA_FILE), { recursive: true });
let saveTimer = null;
function save() {
  clearTimeout(saveTimer);
  saveTimer = setTimeout(flush, 300);
}
function flush() {
  const tmp = DATA_FILE + '.tmp';
  fs.writeFileSync(tmp, JSON.stringify(db));
  fs.renameSync(tmp, DATA_FILE);
  try { const bak = DATA_FILE + '.bak'; if (!fs.existsSync(bak) || Date.now() - fs.statSync(bak).mtimeMs > 3600e3) fs.copyFileSync(DATA_FILE, bak); } catch (e) {}
}
Object.keys(db.sessions).forEach(k => { if (db.sessions[k].exp < Date.now()) delete db.sessions[k]; });
process.on('SIGINT', () => { flush(); process.exit(0); });
process.on('SIGTERM', () => { flush(); process.exit(0); });

/* ---------- עזרים ---------- */
const normName = v => String(v || '').trim().replace(/\s+/g, ' ').toLowerCase();
const sha = s => crypto.createHash('sha256').update(s).digest('hex');
const rid = n => crypto.randomBytes(n).toString('hex');
function scrypt(pw, salt) {
  return new Promise((res, rej) => crypto.scrypt(pw, salt, 64, (e, k) => e ? rej(e) : res(k.toString('hex'))));
}
function send(res, code, body, headers) {
  const h = Object.assign({ 'Cache-Control': 'no-store', 'X-Content-Type-Options': 'nosniff' }, headers || {});
  if (typeof body === 'object' && !Buffer.isBuffer(body)) { body = JSON.stringify(body); h['Content-Type'] = 'application/json; charset=utf-8'; }
  res.writeHead(code, h); res.end(body);
}
function readBody(req) {
  return new Promise((res, rej) => {
    let n = 0; const ch = [];
    req.on('data', c => { n += c.length; if (n > MAX_BODY) { rej(new Error('big')); req.destroy(); } else ch.push(c); });
    req.on('end', () => { try { res(ch.length ? JSON.parse(Buffer.concat(ch).toString('utf8')) : {}); } catch (e) { rej(new Error('json')); } });
    req.on('error', rej);
  });
}
function cookies(req) {
  const o = {}; (req.headers.cookie || '').split(';').forEach(p => { const i = p.indexOf('='); if (i > 0) o[p.slice(0, i).trim()] = decodeURIComponent(p.slice(i + 1).trim()); });
  return o;
}
function userFor(req) {
  const t = cookies(req).sid; if (!t) return null;
  const s = db.sessions[sha(t)];
  if (!s || s.exp < Date.now()) return null;
  if (s.exp - Date.now() < SESSION_MS - 3600e3) { s.exp = Date.now() + SESSION_MS; save(); }
  return db.users[s.u] || null;
}
function setCookie(req, token, maxAge) {
  const secure = (req.headers['x-forwarded-proto'] === 'https') ? '; Secure' : '';
  return 'sid=' + token + '; HttpOnly; SameSite=Lax; Path=/; Max-Age=' + maxAge + secure;
}
function newSession(req, res, user) {
  const t = rid(32);
  db.sessions[sha(t)] = { u: user.name, exp: Date.now() + SESSION_MS };
  save();
  return setCookie(req, t, Math.floor(SESSION_MS / 1000));
}
// הגבלת ניסיונות כניסה
const fails = new Map();
function tooMany(ip) { const f = fails.get(ip); return f && f.n >= 10 && Date.now() - f.t < 10 * 60 * 1000; }
function fail(ip) { const f = fails.get(ip); if (!f || Date.now() - f.t > 10 * 60 * 1000) fails.set(ip, { n: 1, t: Date.now() }); else { f.n++; f.t = Date.now(); } }
const ipOf = req => (req.headers['x-forwarded-for'] || req.socket.remoteAddress || '').split(',')[0].trim();


/* ---------- אימייל, סיסמה ואיפוס ---------- */
const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/;
const TERMS_V = 1;
const RESEND_KEY = process.env.RESEND_API_KEY || '';
const MAIL_FROM = process.env.MAIL_FROM || 'סט <onboarding@resend.dev>';
function pwProblem(pw) {
  if (pw.length < 8) return 'הסיסמה צריכה להכיל לפחות 8 תווים';
  if (!/[A-Za-z\u0590-\u05FF]/.test(pw) || !/\d/.test(pw)) return 'הסיסמה צריכה לכלול אותיות וגם ספרות';
  return '';
}
function sendMail(to, subject, html) {
  if (!RESEND_KEY) { console.log('[mail לא מוגדר] ל:', to, '|', subject, '|', html); return Promise.resolve(false); }
  return new Promise(resolve => {
    const body = JSON.stringify({ from: MAIL_FROM, to: [to], subject, html });
    const r = require('https').request('https://api.resend.com/emails', { method: 'POST', headers: { Authorization: 'Bearer ' + RESEND_KEY, 'Content-Type': 'application/json', 'Content-Length': Buffer.byteLength(body) } }, resp => { resp.resume(); resp.on('end', () => resolve(resp.statusCode < 300)); });
    r.on('error', () => resolve(false)); r.setTimeout(10000, () => { r.destroy(); resolve(false); }); r.end(body);
  });
}
const mailFails = new Map();

/* ---------- הרשאות לנתונים ---------- */
// trainees/<uid>  : המתאמן כותב ומעדכן את שלו. המאמן שאליו הוא משויך קורא.
// coach/<uid>     : המאמן של המתאמן כותב. המתאמן קורא את שלו.
// coaches/<uid>   : מאמן כותב את שלו. כולם קוראים (רשימת המאמנים).
const PATH_RE = /^(trainees|coach|coaches)\/([A-Za-z0-9]{1,40})$/;
function parsePath(p) { const m = PATH_RE.exec(String(p || '')); return m ? { col: m[1], id: m[2] } : null; }
function isCoach(u) { return u.role === 'coach'; }
function canRead(u, { col, id }) {
  if (col === 'coaches') return true;
  if (id === u.id) return true;
  const tr = db.docs['trainees/' + id];
  return isCoach(u) && !!tr && tr.coachUid === u.id;
}
function canWrite(u, { col, id }) {
  if (col === 'trainees') return id === u.id;
  if (col === 'coaches') return isCoach(u) && id === u.id;
  if (col === 'coach') { const tr = db.docs['trainees/' + id]; return isCoach(u) && !!tr && tr.coachUid === u.id; }
  return false;
}

/* ---------- ממשק ---------- */
async function api(req, res, url) {
  const ip = ipOf(req);
  if (req.method === 'POST' && url.pathname === '/api/register') {
    const b = await readBody(req);
    const name = normName(b.username);
    const pw = String(b.password || '');
    const role = b.role === 'coach' ? 'coach' : 'trainee';
    if (!/^[a-z0-9_.֐-׿ -]{3,24}$/.test(name)) return send(res, 400, { error: 'שם משתמש: 3 עד 24 תווים (אותיות, ספרות, רווח, נקודה או קו תחתון)' });
    const email = String(b.email || '').trim().toLowerCase();
    if (!EMAIL_RE.test(email) || email.length > 120) return send(res, 400, { error: 'נא להזין כתובת אימייל תקינה' });
    if (b.terms !== true) return send(res, 400, { error: 'יש לאשר את תנאי השימוש כדי להירשם' });
    const pwErr = pwProblem(pw); if (pwErr) return send(res, 400, { error: pwErr });
    if (b.password2 !== undefined && String(b.password2) !== pw) return send(res, 400, { error: 'הסיסמאות אינן זהות' });
    if (Object.values(db.users).some(u => u.email === email)) return send(res, 409, { error: 'כתובת האימייל כבר רשומה' });
    if (role === 'coach' && COACH_KEY && b.key !== COACH_KEY) return send(res, 403, { error: 'קוד ההרשמה למאמנים שגוי' });
    if (db.users[name]) return send(res, 409, { error: 'שם המשתמש תפוס, בחר אחר' });
    const salt = rid(16);
    const user = { id: rid(8), name, role, email, terms: { at: Date.now(), v: TERMS_V }, salt, hash: await scrypt(pw, salt), created: Date.now() };
    db.users[name] = user;
    return send(res, 200, { ok: true }, { 'Set-Cookie': newSession(req, res, user) });
  }
  if (req.method === 'POST' && url.pathname === '/api/login') {
    if (tooMany(ip)) return send(res, 429, { error: 'יותר מדי ניסיונות. נסה שוב בעוד כמה דקות' });
    const b = await readBody(req);
    const user = db.users[normName(b.username)];
    const ok = user && crypto.timingSafeEqual(Buffer.from(await scrypt(String(b.password || ''), user.salt), 'hex'), Buffer.from(user.hash, 'hex'));
    if (!ok) { fail(ip); return send(res, 401, { error: 'שם משתמש או סיסמה שגויים' }); }
    return send(res, 200, { ok: true }, { 'Set-Cookie': newSession(req, res, user) });
  }
  if (req.method === 'POST' && url.pathname === '/api/forgot') {
    if (tooMany(ip)) return send(res, 429, { error: 'יותר מדי ניסיונות. נסה שוב בעוד כמה דקות' });
    fail(ip);
    const b = await readBody(req);
    const email = String(b.email || '').trim().toLowerCase();
    const user = EMAIL_RE.test(email) && Object.values(db.users).find(u => u.email === email);
    if (user) {
      const t = rid(24);
      Object.keys(db.resets).forEach(k => { if (db.resets[k].u === user.name || db.resets[k].exp < Date.now()) delete db.resets[k]; });
      db.resets[sha(t)] = { u: user.name, exp: Date.now() + 3600e3 };
      save();
      const base = process.env.BASE_URL || ('https://' + (req.headers.host || ''));
      const link = base + '/?reset=' + t;
      sendMail(email, 'איפוס סיסמה באפליקציית סט', '<div dir="rtl" style="font-family:Arial,sans-serif"><p>קיבלנו בקשה לאיפוס הסיסמה שלך.</p><p><a href="' + link + '">לחץ כאן לבחירת סיסמה חדשה</a></p><p>הקישור תקף לשעה. אם לא ביקשת, אפשר להתעלם מההודעה.</p></div>');
    }
    return send(res, 200, { ok: true });
  }
  if (req.method === 'POST' && url.pathname === '/api/reset') {
    if (tooMany(ip)) return send(res, 429, { error: 'יותר מדי ניסיונות. נסה שוב בעוד כמה דקות' });
    const b = await readBody(req);
    const r = db.resets[sha(String(b.token || ''))];
    const pw = String(b.password || '');
    if (!r || r.exp < Date.now() || !db.users[r.u]) { fail(ip); return send(res, 400, { error: 'הקישור פג תוקף או לא תקין. בקש קישור חדש' }); }
    const pwErr = pwProblem(pw); if (pwErr) return send(res, 400, { error: pwErr });
    const user = db.users[r.u];
    user.salt = rid(16); user.hash = await scrypt(pw, user.salt);
    delete db.resets[sha(String(b.token))];
    Object.keys(db.sessions).forEach(k => { if (db.sessions[k].u === user.name) delete db.sessions[k]; });
    save();
    return send(res, 200, { ok: true }, { 'Set-Cookie': newSession(req, res, user) });
  }
  if (req.method === 'POST' && url.pathname === '/api/logout') {
    const t = cookies(req).sid; if (t) { delete db.sessions[sha(t)]; save(); }
    return send(res, 200, { ok: true }, { 'Set-Cookie': setCookie(req, '', 0) });
  }
  const me = userFor(req);
  if (!me) return send(res, 401, { error: 'auth' });
  if (req.method === 'POST' && url.pathname === '/api/account/delete') {
    if (tooMany(ip)) return send(res, 429, { error: 'יותר מדי ניסיונות. נסה שוב בעוד כמה דקות' });
    const b = await readBody(req);
    const ok2 = crypto.timingSafeEqual(Buffer.from(await scrypt(String(b.password || ''), me.salt), 'hex'), Buffer.from(me.hash, 'hex'));
    if (!ok2) { fail(ip); return send(res, 403, { error: 'הסיסמה שגויה' }); }
    ['trainees/', 'coach/', 'coaches/'].forEach(c => { delete db.docs[c + me.id]; });
    Object.keys(db.sessions).forEach(k => { if (db.sessions[k].u === me.name) delete db.sessions[k]; });
    Object.keys(db.passkeys || {}).forEach(k => { if (db.passkeys[k].user === me.name) delete db.passkeys[k]; });
    Object.keys(db.resets || {}).forEach(k => { if (db.resets[k].u === me.name) delete db.resets[k]; });
    if (db.push) delete db.push[me.id];
    Object.keys(db.videos || {}).forEach(k => { const v = db.videos[k]; if (v.owner === me.id) { try { fs.unlinkSync(path.join(path.dirname(DATA_FILE), 'videos', v.id + '.' + v.ext)); } catch (e) {} delete db.videos[k]; } });
    delete db.users[me.name];
    save();
    return send(res, 200, { ok: true }, { 'Set-Cookie': setCookie(req, '', 0) });
  }
  if (req.method === 'POST' && url.pathname === '/api/email') {
    const b = await readBody(req);
    const email = String(b.email || '').trim().toLowerCase();
    if (!EMAIL_RE.test(email)) return send(res, 400, { error: 'נא להזין כתובת אימייל תקינה' });
    if (Object.values(db.users).some(u => u.email === email && u !== me)) return send(res, 409, { error: 'כתובת האימייל כבר רשומה' });
    me.email = email; if (!me.terms) me.terms = { at: Date.now(), v: TERMS_V }; save();
    return send(res, 200, { ok: true });
  }

  if (req.method === 'GET' && url.pathname === '/api/doc') {
    const p = parsePath(url.searchParams.get('path'));
    if (!p || !canRead(me, p)) return send(res, 403, { error: 'forbidden' });
    const d = db.docs[p.col + '/' + p.id];
    return send(res, 200, d === undefined ? { exists: false } : { exists: true, data: d });
  }
  if (req.method === 'PUT' && url.pathname === '/api/doc') {
    const b = await readBody(req);
    const p = parsePath(b.path);
    if (!p || !canWrite(me, p) || !b.value || typeof b.value !== 'object' || Array.isArray(b.value)) return send(res, 403, { error: 'forbidden' });
    db.docs[p.col + '/' + p.id] = b.value; save();
    return send(res, 200, { ok: true });
  }
  if (req.method === 'GET' && url.pathname === '/api/col') {
    const col = url.searchParams.get('path');
    const docs = [];
    if (col === 'coaches') {
      for (const k in db.docs) if (k.startsWith('coaches/')) docs.push({ id: k.slice(8), data: db.docs[k] });
    } else if (col === 'trainees' && isCoach(me)) {
      for (const k in db.docs) if (k.startsWith('trainees/') && db.docs[k].coachUid === me.id) docs.push({ id: k.slice(9), data: db.docs[k] });
    } else return send(res, 403, { error: 'forbidden' });
    return send(res, 200, { docs });
  }
  return send(res, 404, { error: 'not found' });
}

/* ---------- דפים ---------- */
const SHIM = `(function(){var ME=window.__ME;
function api(m,u,b){return fetch(u,{method:m,credentials:'same-origin',headers:b?{'content-type':'application/json'}:{},body:b?JSON.stringify(b):undefined}).then(function(r){if(r.status===401){location.reload();throw new Error('auth')}if(!r.ok)throw new Error('http'+r.status);return r.json()})}
function ref(p){return {get:function(){return api('GET','/api/doc?path='+encodeURIComponent(p)).then(function(x){return {exists:function(){return x.exists},data:function(){return x.data}}})},set:function(v){return api('PUT','/api/doc',{path:p,value:v})}}}
var user={isOwner:function(){return Promise.resolve(ME.role==='coach')},canEdit:function(){return Promise.resolve(ME.role==='coach')},id:function(){return Promise.resolve(ME.id)}};
var dbo={doc:ref,collection:function(p){return {get:function(){return api('GET','/api/col?path='+encodeURIComponent(p)).then(function(x){return {docs:x.docs.map(function(d){return {id:d.id,data:function(){return d.data}}})}})}}}};
window.claude={use:function(n){return Promise.resolve(n==='user'?user:n==='db'?dbo:null)}};
document.addEventListener('DOMContentLoaded',function(){var t=document.querySelector('.top');if(!t)return;var b=document.createElement('button');b.type='button';b.className='linkbtn';b.textContent='יציאה';b.title=ME.name;b.style.marginInlineStart='8px';b.onclick=function(){fetch('/api/logout',{method:'POST'}).then(function(){location.reload()})};t.appendChild(b)});
})();`;
const FILES = {
  'app.html': '',
  'login.html': ''
};
const read = f => Buffer.from(FILES[f], 'base64').toString('utf8');
function appPage(me) {
  const info = JSON.stringify({ id: me.id, name: me.name, role: me.role, email: me.email || '' }).replace(/</g, '\\u003c');
  return read('app.html').replace('<head>', '<head><link rel="manifest" href="/manifest.webmanifest"><link rel="apple-touch-icon" href="/icon-192.png"><script>window.__ME=' + info + ';' + SHIM + '</script>');
}

const pushHandle = require('./push.js')(db, save, send, readBody, userFor);
const pkHandle = require('./passkey.js')(db, save, send, readBody, userFor, newSession);
const videoHandle = require('./video.js')(db, save, send, userFor, DATA_FILE);
const STATIC = { '/sw.js': ['application/javascript; charset=utf-8', 'sw.js'], '/manifest.webmanifest': ['application/manifest+json; charset=utf-8', 'manifest.webmanifest'], '/icon-192.png': ['image/png', 'icon-192.png'], '/icon-512.png': ['image/png', 'icon-512.png'] };
const server = http.createServer(async (req, res) => {
  try {
    const url = new URL(req.url, 'http://x');
    if (req.method === 'GET' && STATIC[url.pathname]) return send(res, 200, fs.readFileSync(path.join(__dirname, 'static', STATIC[url.pathname][1])), { 'Content-Type': STATIC[url.pathname][0], 'Cache-Control': 'no-cache' });
    if (url.pathname.startsWith('/api/push') && await pushHandle(req, res, url)) return;
    if (url.pathname.startsWith('/api/pk/') && await pkHandle(req, res, url)) return;
    if (url.pathname.startsWith('/api/video') && await videoHandle(req, res, url)) return;
    if (url.pathname === '/healthz') return send(res, 200, 'ok');
    if (url.pathname.startsWith('/api/')) return await api(req, res, url);
    if (req.method !== 'GET') return send(res, 405, 'x');
    if (url.pathname === '/' || url.pathname === '/index.html') {
      const me = userFor(req);
      return send(res, 200, me ? appPage(me) : read('login.html'), { 'Content-Type': 'text/html; charset=utf-8' });
    }
    return send(res, 404, 'not found');
  } catch (e) {
    send(res, e.message === 'big' ? 413 : 400, { error: 'bad request' });
  }
});
server.listen(PORT, '0.0.0.0', () => {
  console.log('\nהשרת פועל.');
  console.log('במחשב הזה:     http://localhost:' + PORT);
  const nets = require('os').networkInterfaces();
  Object.keys(nets).forEach(n => nets[n].forEach(a => { if (a.family === 'IPv4' && !a.internal) console.log('באותה רשת Wi-Fi: http://' + a.address + ':' + PORT); }));
  console.log(COACH_KEY ? 'הרשמת מאמנים דורשת קוד.' : 'שים לב: כל אחד יכול להירשם כמאמן. מומלץ להגדיר COACH_KEY (ראה README).');
});
